import{_ as e,o,c as a,a2 as n}from"./chunks/framework.CPHNBVkq.js";const h=JSON.parse('{"title":"Getting Started","description":"","frontmatter":{},"headers":[],"relativePath":"guide/getting-started.md","filePath":"guide/getting-started.md"}'),r={name:"guide/getting-started.md"};function i(s,t,l,d,u,g){return o(),a("div",null,[...t[0]||(t[0]=[n('<h1 id="getting-started" tabindex="-1">Getting Started <a class="header-anchor" href="#getting-started" aria-label="Permalink to &quot;Getting Started&quot;">​</a></h1><p>This page gets you signed in, oriented, and set up with your first channel so your Pulse feed has something to show.</p><h2 id="signing-in" tabindex="-1">Signing in <a class="header-anchor" href="#signing-in" aria-label="Permalink to &quot;Signing in&quot;">​</a></h2><p>Corbi uses your organization&#39;s single sign-on. Open Corbi in your browser (or the mobile app) and you&#39;ll be taken to a sign-in screen.</p><ol><li>Choose <strong>Sign In</strong>.</li><li>Sign in with your work account when prompted.</li><li>After signing in, you&#39;ll land in the app.</li></ol><div class="tip custom-block"><p class="custom-block-title">First time signing in?</p><p>Corbi automatically detects your time zone from your device the first time you sign in. You can change it later — see <a href="./notifications.html#time-zone">Notifications &amp; Daily Summary</a>.</p></div><h2 id="finding-your-way-around" tabindex="-1">Finding your way around <a class="header-anchor" href="#finding-your-way-around" aria-label="Permalink to &quot;Finding your way around&quot;">​</a></h2><p>A navigation drawer runs down the left side of the screen. On a wide screen it can be expanded or collapsed; on a narrow screen or phone it opens as a slide-out menu.</p><p>The drawer is where you switch between the main areas of Corbi:</p><table tabindex="0"><thead><tr><th>Area</th><th>What it&#39;s for</th></tr></thead><tbody><tr><td><strong>Pulse</strong></td><td>Your feed of business updates.</td></tr><tr><td><strong>Chat</strong></td><td>Conversations with Corbi.</td></tr><tr><td><strong>Tasks</strong></td><td>Tasks you&#39;ve asked Corbi to create.</td></tr><tr><td><strong>Settings</strong></td><td>Notification preferences, channels, and account options.</td></tr></tbody></table><blockquote><p>📷 <strong>Screenshot:</strong> <em>Navigation drawer (expanded) — coming soon.</em></p></blockquote><div class="info custom-block"><p class="custom-block-title">Don&#39;t see all of these?</p><p>The areas you see depend on your account&#39;s access. If Pulse, Chat, or Tasks aren&#39;t in your drawer, your organization may not have enabled them for you.</p></div><h2 id="your-first-steps" tabindex="-1">Your first steps <a class="header-anchor" href="#your-first-steps" aria-label="Permalink to &quot;Your first steps&quot;">​</a></h2><p>To get value out of Corbi right away:</p><ol><li><strong>Create a channel.</strong> Your Pulse feed is empty until you tell Corbi what to follow. Go to <strong>Settings → Manage Channels</strong> and add one. See <a href="./channels-create.html">Creating a Channel</a> for a walkthrough.</li><li><strong>Read your Pulse feed.</strong> Once a channel is set up, open <strong>Pulse</strong> to see updates roll in. See <a href="./pulse-feed.html">Pulse Feed</a>.</li><li><strong>Turn on your Daily Summary</strong> (optional). If you&#39;d rather get a once-a-day recap by email, enable it in <strong>Settings → Notification Preferences</strong>. See <a href="./notifications.html">Notifications &amp; Daily Summary</a>.</li></ol><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>If you open Pulse and see &quot;No Channels Found,&quot; that&#39;s expected before you&#39;ve set anything up. Select <strong>Create Channel</strong> right from that screen to get started.</p></div>',16)])])}const p=e(r,[["render",i]]);export{h as __pageData,p as default};
